using RecipeShare.Models;

namespace RecipeShare.Services;

public class RecipeService
{
    private readonly List<Recipe> _recipes = new()
    {
        new Recipe { Id = 1, Title = "Classic Margherita Pizza", Category = "Italian", Ingredients = "Pizza dough, Fresh mozzarella, San Marzano tomatoes, Fresh basil, Olive oil", Steps = "1. Preheat oven to 475°F\n2. Roll out dough\n3. Spread crushed tomatoes\n4. Add torn mozzarella\n5. Bake 10-12 minutes\n6. Top with fresh basil", AverageRating = 4.5, RatingCount = 12 },
        new Recipe { Id = 2, Title = "Chicken Tikka Masala", Category = "Indian", Ingredients = "Chicken thighs, Yogurt, Garam masala, Tomato sauce, Cream, Onion, Garlic, Ginger", Steps = "1. Marinate chicken in yogurt and spices\n2. Grill or broil chicken\n3. Sauté onions, garlic, ginger\n4. Add tomato sauce and cream\n5. Add chicken to sauce\n6. Simmer 15 minutes", AverageRating = 4.8, RatingCount = 24 },
        new Recipe { Id = 3, Title = "Spaghetti Carbonara", Category = "Italian", Ingredients = "Spaghetti, Guanciale, Eggs, Pecorino Romano, Black pepper", Steps = "1. Cook pasta al dente\n2. Crisp guanciale in a pan\n3. Whisk eggs with cheese\n4. Toss hot pasta with guanciale\n5. Add egg mixture off heat\n6. Serve with extra cheese and pepper", AverageRating = 4.3, RatingCount = 8 },
        new Recipe { Id = 4, Title = "Pad Thai", Category = "Thai", Ingredients = "Rice noodles, Shrimp, Eggs, Bean sprouts, Peanuts, Tamarind paste, Fish sauce, Lime", Steps = "1. Soak rice noodles\n2. Stir-fry shrimp until pink\n3. Push aside, scramble eggs\n4. Add noodles and sauce\n5. Toss with bean sprouts\n6. Garnish with peanuts and lime", AverageRating = 4.6, RatingCount = 15 },
        new Recipe { Id = 5, Title = "Beef Tacos", Category = "Mexican", Ingredients = "Ground beef, Taco seasoning, Corn tortillas, Lettuce, Tomato, Cheese, Sour cream, Salsa", Steps = "1. Brown ground beef\n2. Add taco seasoning and water\n3. Simmer until thickened\n4. Warm tortillas\n5. Assemble with toppings\n6. Serve with salsa", AverageRating = 4.1, RatingCount = 19 },
        new Recipe { Id = 6, Title = "Miso Soup", Category = "Japanese", Ingredients = "Dashi stock, White miso paste, Tofu, Wakame seaweed, Green onions", Steps = "1. Heat dashi stock\n2. Dissolve miso paste into stock\n3. Add cubed tofu\n4. Add rehydrated wakame\n5. Heat gently (don't boil)\n6. Garnish with green onions", AverageRating = 4.0, RatingCount = 6 },
        new Recipe { Id = 7, Title = "Guacamole", Category = "Mexican", Ingredients = "Avocados, Lime juice, Cilantro, Red onion, Jalapeño, Tomato, Salt", Steps = "1. Halve and pit avocados\n2. Mash to desired consistency\n3. Add lime juice and salt\n4. Fold in diced onion, tomato, jalapeño\n5. Add chopped cilantro\n6. Serve immediately with chips", AverageRating = 4.7, RatingCount = 21 },
        new Recipe { Id = 8, Title = "Green Curry", Category = "Thai", Ingredients = "Green curry paste, Coconut milk, Chicken, Thai basil, Bamboo shoots, Fish sauce, Sugar", Steps = "1. Fry curry paste in coconut cream\n2. Add sliced chicken\n3. Pour in remaining coconut milk\n4. Add bamboo shoots\n5. Season with fish sauce and sugar\n6. Finish with Thai basil", AverageRating = 4.4, RatingCount = 11 },
    };

    private readonly Dictionary<int, List<int>> _ratings = new();

    public List<string> GetCategories()
    {
        return _recipes.Select(r => r.Category).Distinct().OrderBy(c => c).ToList();
    }

    public List<Recipe> GetRecipesByCategory(string category)
    {
        return _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();
    }

    public Recipe? GetRecipeById(int id)
    {
        return _recipes.FirstOrDefault(r => r.Id == id);
    }

    public void AddRating(int recipeId, int stars)
    {
        var recipe = _recipes.FirstOrDefault(r => r.Id == recipeId);
        if (recipe == null || stars < 1 || stars > 5) return;

        if (!_ratings.ContainsKey(recipeId))
            _ratings[recipeId] = new List<int>();

        _ratings[recipeId].Add(stars);

        var allRatings = _ratings[recipeId];
        recipe.AverageRating = Math.Round(allRatings.Average(), 1);
        recipe.RatingCount = allRatings.Count;
    }

    public void SubmitRecipe(RecipeSubmission submission)
    {
        var newId = _recipes.Max(r => r.Id) + 1;
        _recipes.Add(new Recipe
        {
            Id = newId,
            Title = submission.Title,
            Category = submission.Category,
            Ingredients = submission.Ingredients,
            Steps = submission.Steps,
            AverageRating = 0,
            RatingCount = 0
        });
    }
}

