@page "/"

<PageTitle>RecipeShare - Home</PageTitle>

<h1>🍳 RecipeShare</h1>
<p class="lead">Discover and share delicious recipes from around the world.</p>

<h2>Browse by Category</h2>
<div class="row">
    @foreach (var category in Categories)
    {
        <div class="col-md-4 mb-3">
            <div class="card h-100">
                <div class="card-body">
                    <h5 class="card-title">@GetCategoryEmoji(category) @category</h5>
                    <p class="card-text">Explore our collection of @category recipes.</p>
                    <a href="/recipes/@category.ToLower()" class="btn btn-primary">Browse</a>
                </div>
            </div>
        </div>
    }
</div>

<hr class="my-4" />

<div class="text-center">
    <h3>Have a recipe to share?</h3>
    <a href="/submit" class="btn btn-success btn-lg">Submit a Recipe</a>
</div>

@code {
    [Inject] public RecipeShare.Services.RecipeService RecipeService { get; set; } = default!;

    private List<string> Categories = new();

    protected override void OnInitialized()
    {
        Categories = RecipeService.GetCategories();
    }

    private string GetCategoryEmoji(string category) => category switch
    {
        "Italian" => "🇮🇹",
        "Indian" => "🇮🇳",
        "Thai" => "🇹🇭",
        "Mexican" => "🇲🇽",
        "Japanese" => "🇯🇵",
        _ => "🍽️"
    };
}

